#!/usr/bin/env python3
"""BINGO-TOOL 木製抽選機: アップロード前に手元で確認するインストーラー"""
import base64,io,zipfile,shutil,datetime
from pathlib import Path
TARGET=Path.home()/"storage/downloads/ゲーム/BINGO-TOOL"
ARCHIVE=""""""
if not TARGET.is_dir() or not (TARGET/"index.html").exists():
    raise SystemExit("エラー: BINGO-TOOL/index.html がありません。変更なし。")
with zipfile.ZipFile(io.BytesIO(base64.b64decode(ARCHIVE))) as z:
    files=[p for p in z.namelist() if p in {"index.html","css/style.css","js/script.js","js/audio-data.js"}]
    if len(files)!=4: raise SystemExit("エラー: ファイル構成が不正。変更なし。")
    backup=Path.home()/"bingo-backups"/datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
    for name in files:
        dst=TARGET/name
        if dst.exists():
            saved=backup/name;saved.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(dst,saved)
    for name in files:
        dst=TARGET/name;dst.parent.mkdir(parents=True,exist_ok=True)
        dst.write_bytes(z.read(name))
print("成功: 木製ビンゴ抽選機と2つの効果音を導入しました。")
print("既存ファイルのバックアップ:",backup)
print("まず index.html を開いて音と動きを確認してください。")
print("問題なければ uploadbingo を実行してください。")
